package vn.alarm.pro;
import android.app.*;import android.content.*;import android.media.*;import android.os.*;import android.speech.tts.*;import java.util.*;import org.json.*;
public class RingService extends Service {TextToSpeech tts;MediaPlayer player;Handler handler=new Handler();Vibrator vib;int old=-1;AudioManager audio;boolean active;String note="";int id;
 public IBinder onBind(Intent i){return null;}
 public int onStartCommand(Intent i,int flags,int start){if(i==null){stopSelf();return START_NOT_STICKY;}id=i.getIntExtra("id",-1);JSONObject o=Store.get(this,id);if(o==null){stopSelf();return START_NOT_STICKY;}note=o.optString("note");NotificationManager nm=getSystemService(NotificationManager.class);NotificationChannel ch=new NotificationChannel("ring","Báo thức",NotificationManager.IMPORTANCE_HIGH);ch.setSound(null,null);nm.createNotificationChannel(ch);PendingIntent p=PendingIntent.getActivity(this,id,new Intent(this,RingActivity.class).putExtra("id",id),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);startForeground(1,new Notification.Builder(this,"ring").setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle("Đến giờ báo thức!").setContentText(note).setCategory(Notification.CATEGORY_ALARM).setFullScreenIntent(p,true).setContentIntent(p).setOngoing(true).build());if(active)return START_NOT_STICKY;active=true;audio=getSystemService(AudioManager.class);old=audio.getStreamVolume(AudioManager.STREAM_ALARM);try{audio.setStreamVolume(AudioManager.STREAM_ALARM,Math.round(audio.getStreamMaxVolume(AudioManager.STREAM_ALARM)*o.optInt("volume",100)/100f),0);}catch(Exception e){}try{player=new MediaPlayer();player.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ALARM).build());player.setDataSource(this,RingtoneManager.getDefaultUri(RingtoneManager.TYPE_ALARM));player.setLooping(true);player.prepare();player.start();}catch(Exception e){}if(o.optBoolean("vibrate",true)){vib=getSystemService(Vibrator.class);vib.vibrate(VibrationEffect.createWaveform(new long[]{0,700,500},0));}tts=new TextToSpeech(this,status->{if(status==TextToSpeech.SUCCESS&&active){tts.setLanguage(new Locale("vi","VN"));tts.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ALARM).build());handler.postDelayed(speak,2500);}});return START_NOT_STICKY;}
 Runnable speak=new Runnable(){public void run(){if(!active)return;if(tts!=null&&!note.isEmpty()){if(player!=null)player.setVolume(.15f,.15f);tts.speak(note,TextToSpeech.QUEUE_FLUSH,null,"note");handler.postDelayed(()->{if(active&&player!=null)player.setVolume(1,1);},Math.max(5000,note.length()*100L));}handler.postDelayed(this,20000);}};
 public void onDestroy(){active=false;handler.removeCallbacksAndMessages(null);if(player!=null)player.release();if(tts!=null)tts.shutdown();if(vib!=null)vib.cancel();if(old>=0)try{audio.setStreamVolume(AudioManager.STREAM_ALARM,old,0);}catch(Exception e){}super.onDestroy();}
}